'use strict';

function normalize(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function validEmail(email) {
  if (/\s/.test(email)) return false;
  const firstAt = email.indexOf('@');
  if (firstAt <= 0 || firstAt !== email.lastIndexOf('@')) return false;
  const domain = email.slice(firstAt + 1);
  return domain.length > 0;
}

function validateProfile(input) {
  const source = input && typeof input === 'object' && !Array.isArray(input)
    ? input
    : {};
  const value = {
    displayName: normalize(source.displayName),
    email: normalize(source.email),
    biography: normalize(source.biography)
  };
  const errors = {};
  if (value.displayName.length < 2 || value.displayName.length > 40) {
    errors.displayName = 'INVALID_DISPLAY_NAME';
  }
  if (!validEmail(value.email)) errors.email = 'INVALID_EMAIL';
  if (value.biography.length < 10 || value.biography.length > 500) {
    errors.biography = 'INVALID_BIOGRAPHY';
  }
  return { ok: Object.keys(errors).length === 0, errors, value };
}

module.exports = { validateProfile };

