'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['validateProfile']);
const { validateProfile } = api;

const input = {
  displayName: '  Ada Lovelace  ',
  email: '  ada@example.com ',
  biography: '  First computer programmer.  '
};
const valid = validateProfile(input);
assert.deepEqual(valid, {
  ok: true,
  errors: {},
  value: {
    displayName: 'Ada Lovelace',
    email: 'ada@example.com',
    biography: 'First computer programmer.'
  }
});
assert.notStrictEqual(valid.value, input);
assert.deepEqual(input, {
  displayName: '  Ada Lovelace  ',
  email: '  ada@example.com ',
  biography: '  First computer programmer.  '
});

for (const badInput of [null, undefined, 7, 'profile', [], {}]) {
  const result = validateProfile(badInput);
  assert.equal(result.ok, false);
  assert.deepEqual(result.value, { displayName: '', email: '', biography: '' });
  assert.deepEqual(result.errors, {
    displayName: 'INVALID_DISPLAY_NAME',
    email: 'INVALID_EMAIL',
    biography: 'INVALID_BIOGRAPHY'
  });
}

const wrongTypes = validateProfile({ displayName: 12, email: {}, biography: false });
assert.deepEqual(wrongTypes.value, { displayName: '', email: '', biography: '' });
assert.deepEqual(Object.keys(wrongTypes.errors).sort(), ['biography', 'displayName', 'email']);

const name2 = 'ab';
const name40 = 'x'.repeat(40);
const bio10 = 'b'.repeat(10);
const bio500 = 'c'.repeat(500);
assert.equal(validateProfile({ displayName: name2, email: 'a@b.co', biography: bio10 }).ok, true);
assert.equal(validateProfile({ displayName: name40, email: 'x@y.co', biography: bio500 }).ok, true);
assert.equal(validateProfile({ displayName: 'a', email: 'a@b.co', biography: bio10 }).errors.displayName, 'INVALID_DISPLAY_NAME');
assert.equal(validateProfile({ displayName: 'x'.repeat(41), email: 'a@b.co', biography: bio10 }).errors.displayName, 'INVALID_DISPLAY_NAME');
assert.equal(validateProfile({ displayName: 'Good', email: 'a@b.co', biography: 'x'.repeat(9) }).errors.biography, 'INVALID_BIOGRAPHY');
assert.equal(validateProfile({ displayName: 'Good', email: 'a@b.co', biography: 'x'.repeat(501) }).errors.biography, 'INVALID_BIOGRAPHY');

for (const email of ['abc', '@example.com', 'a@', 'a@@example.com', 'a b@example.com', 'a@ example.com', 'a@example', 'a@.com', 'a@example.', 'a@.', 'a@com']) {
  const result = validateProfile({ displayName: 'Valid Name', email, biography: 'Long enough biography' });
  assert.equal(result.ok, false, email);
  assert.equal(result.errors.email, 'INVALID_EMAIL', email);
}

const first = validateProfile(input);
const second = validateProfile(input);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.value, second.value);
assert.notStrictEqual(first.errors, second.errors);
first.value.displayName = 'changed';
assert.equal(second.value.displayName, 'Ada Lovelace');

